def lcm(x, y):
    return x * y // gcd(x, y)

def find_lcs_length(bn, times, t):
    max_lcs = 1
    least_common_multiple = bn[0]
    for i in range(1, bn[0], t):
        mod = bn[i] % bn[0]
        lcm_value = bn[0]
        for j in range(i + 1, bn[0], mod):
            lcm_value = lcm(lcm_value + 1, mod)
        diff = [bn[i] - mod, bn[i] - lcm_value]
        for d in diff:
            if d > 0:
                if mod is 0:
                    d = 1
                least_common_multiple = lcm(least_common_multiple, d)
                if times is 0 and least_common_multiple > t:
                    return 0
                times -= 1
        max_lcs += least_common_multiple - least_common_multiple % t
    return max_lcs

