def guess_number(x, queries_left, last_num=None):
    if last_num is not None:
        print(f"{x} {last_num}")
    else:
        print(f"{1} {1}")  # Guess the smallest number
    queries_left -= 1
    if queries_left <= 0:
        return 1  # Complete the path
    response = int(input())
    while response < 0 or response > queries_left:
        print(f"{x} {0}")  # Reset and try again from the smallest
        response = int(input())
    if response == 0:
        last_num = x
        x += 1
    elif response == queries_left:
        last_num = x
        x -= 1
    else:
        i = response + 1
        t = x - i + 1
        if t == 1:
            last_num += 1
        elif t == x - 1:
            last_num -= 1
        else:
            for num in range(t, 2 * t, 2):
                if last_num < num:
                    last_num = num
                else:
                    break
        x = t
    return last_num

