def freeze_positions(positions):
    positions.sort()
    queue = []
    for i in range(len(positions) - 1, -1, -1):
        if len(queue) == 0:
            queue.append(i)
        else:
            if positions[i] > queue[-1]:
                queue = [i]
            else:
                queue.append(i)
    return len(positions) - len(queue)

def execute_moves(positions, moves):
    last_move = 0
    for move in moves:
        if move == "L":
            positions[last_move] -= 1
            last_move = (last_move - 1 + len(positions)) % len(positions)
        elif move == "R":
            if last_move + 1 < len(positions):
                positions[last_move] -= 1
                if positions[last_move] == 0:
                    positions[last_move] = 0 if positions[last_move - 1] == 0 else len(positions) - 1
            last_move = (last_move + 1) % len(positions)
        else:
            positions[last_move] -= 1
            queue = [i for i in range(last_move) if positions[i] == 0]
            for i in queue:
                if i != last_move - 1:
                    positions[i] = 0
            last_move = (last_move - 1 + len(positions)) % len(positions)
    return marks_to_map(positions)

def marks_to_map(positions):
    m = {"L": len(positions) - 1, "R": 0, "A": 0}
    for i in range(len(positions)):
        m[positions[i]] = i
    return m

