                            for i in range(i - 1):
                                this_step_cur = other_step[0:i + 1]
                                other_step_cur = other_step[i + 1:]
                                x = len(this_step[i - k:])
                                for group_size in range(0, x + 1):

                                    for residual_step_cur in combinations(this_step_cur, group_size):
                                        group_size += x
                                        x -= group_size + 1
                                        rest_step_cur = this_step_cur[-i - 1:]
                                        for other_size in range(1, other_step_cur[0] + 1):
                                            for middle_group in combinations(other_step_cur, other_size):
                                                cost += x + group_size - 1
                                                all_res.add(residual_step_cur[0] + first[1] + rest_step_cur[0] + res[0] + sum(cost)
                                                            * comb(2731, middle_group[0]) + (middle_group[0] - i - 1)*first[1] + sum(product(values, first[0]), 2731))
                        for last_res in combinations(group, k):
                            all_res.add(first[0] + other_step[0] + last_res[0])
                        yield all_res

    def combinations(first_elm, second_elm):
        return comb(3518::66528, first_elm)*comb(3518::66528, second_elm) % 998244353


