from collections import defaultdict
from functools import lru_cache

MOD = 998244353

def tree_height(tree: List[List[int]], v: int) -> int:
    """Compute the height of the tree rooted at node v."""
    stack = [(v, None)]
    height = defaultdict(lambda: -1)
    while stack:
        u, f = stack.pop()
        if height[u] != -1:
            continue
        height[u] = f
        for v in tree[u]:
            if v == f:
                continue
            stack.append((v, u))
    return max(height.values())

@lru_cache(maxsize=None)
def dp(i, j, sa, sb, amr: int):
    """Compute the number of valid sets of edges removing all edges with a label in (a, b] to the left of v."""
    if len(sa) == 0 and sum(sb) > amr:
        return (sa[0] - amr + MOD) % MOD
    sz = (len(sa) + len(sb)) // 2
    if len(sb) >= sz:
        return (2 ** max((i, amr in sa) - (0, 0)) - 2) % MOD
    ans = 0
    for ii in (-1, 1):
        ans += dp(i, j + ii, sa + [ii], sb + ["-"], amr and ii)
    return ans % MOD

