import sys

def find_solution(n, devils):
    points = [(0, v) for v in devils] + [(1, 0)] + [(2, 0)]
    costs = [0] * (n + 1)
    costs[-1] = 1
    next_to_low = {0: -1}
    for i, (p, v) in enumerate(points):
        if i == n + 1:
            break
        if v > next_to_low.pop(0):
            continue
        costs[i] = costs[next_to_low[v]] + 1
        next_to_low[v] = i

    state = [(1, 0)]  # (cost so far, local min value)
    visited = set()
    L = []
    while state:
        cost, v = state.pop()
        if (cost, v) == (min(cost, 0), next_to_low[v][1]):
            visited.add((cost, v))
            continue

        cost += 1
        if v < n - 1:
            if v < min(costs):
                if (cost, v) not in visited:
                    state.append((cost, v))
            elif v < costs:
                state.append((cost, v))
        elif (cost and n - v > v and v > 0):
            if (cost, v * -1) not in visited:
                L.append('A' * (v * -1))
                state.append((cost, v))
        elif v == n - 1:
            if (cost, -1) not in visited:
                L.append('A' * (v - 1))
                state.append((cost, -1))
    return ''.join(L)

