def sort_indices(arr, n):
    """
    Generate the pairs of indices to swap for sorting the array.
    """
    pq = []
    pairs = set()
    for a in arr:
        if not pq or a >= pq[0][-1]:
            heappush(pq, (a, 0, count(1)))
        else:
            heappush(pq, ((a - pq[0][0]) >> 1, 1, count(1)))
            heappush(pq, (0, -1, count(1)))
        arr[heappop(pq)[1]] = count()
    while pq:
