        tree[(n-2, 2)].append((n-2, 3))
        tree[(n-2, 3)].append((n-3, 2))
        tree[(n-3, 2)].append((n-3, 1))
        tree[(n-3, 1)].append((n-3, 3))
        tree[(n-3, 3)].append((n-4, 3))
        tree[(n-4, 3)].append((n-4, 2))
        tree[(n-4, 2)].append((n-4, 1))
        tree[(n-4, 1)].append((n-4, 4))
        tree[(n-4, 4)].append((n-5, 2))
        tree[(n-5, 2)].append((n-5, 1))
    return tree

def number_of_trees(n: int) -> int:
    small_trees = defaultdict(int)
    small_trees[(n-1, n-1)] = 1
    small_trees[(n-1, n-2)] = 1
    small_trees[(n-2, n-1)] = 1
    for p in [n-1, n-2, n-3]:
        for q in range(n-1):
            small_trees[(p, q)] += small_trees[(p-1, q)]
