        for x, y in P:
            closest_x, closest_y = min([(a, b) for a, b in line], key=lambda pair: distance(pair[0], pair[1], x, y))
            if distance(closest_x, closest_y, x, y) > distance(start_x, start_y, end_x, end_y):
