def find_inversions(arr):
    n = len(arr)
    inversions = []

    # Initialize deque to track indices in ascending order
    queue = deque([0])

    for i in range(1, n):
        if arr[i] < arr[queue[0]]:
            inversions.append((queue[0], i))
            queue.append(i)
        else:
            while queue and arr[queue[-1]] < arr[i]:
