def extended_gcd(a, b):
    """Compute the Extended Euclidean Algorithm: gcd(a, b) and coefficients x, y."""
    if b == 0:
        return a, 1, 0
    else:
        g, x, y = extended_gcd(b, a % b)
        return g, y, x - y * (a // b)

def mod_inverse(a, m):
    """Compute the modular multiplicative inverse of a modulo m."""
    g, x, y = extended_gcd(a, m)
    if g == 1:
        return x % m

def solve(n, a):
    a.sort()
    result = set()
    for i in range(n):
        for j in range(i, n):
            result.add(a[j] ^ a[i])
    return len(result), sorted(result)

