        self.parents = UnionFind(n)
        self.weights = {}

    def process_event(self, event, *args):
        t, v, u, k = event
        if t == 1:
            self.parents.union(*args)
        elif t == 2:
            self.weights[self.parents.find(v)] += k

def query_data(data, query):
