def find_inversions(n, a):
    # Check for sorted array
    if all(a[i] <= a[i+1] for i in range(n-1)):
        return 0

    # Manacher's Algorithm for longest palindromic substring to find odd-length inversion pairs
    def extend_palindrome(center, cache, s):
        left, right = center, center
        while left - 1 >= 0 and right + 1 < n and s[left-1] == s[right+1]:
            left -= 1
            right += 1
        return (left, right)

    max_radius = -1
    for i in range(n):
        for j in range(i+1, n):
            if a[j] < a[i]:
                # Find the longest palindromic substring centered at (i, j)
                pal_dist, _ = extend_palindrome(i, -1, [True]) or extend_palindrome(j, -1, [True])
                if 2 * pal_dist > max_radius and i != 1 and j != n-1:
                    max_radius = 2 * pal_dist
                    # Check extension possibilities and save the span of even longer palin
                    if i != 1 and a[i-1] <= a[j] <= a[i+1]:
                        s, r = extend_palindrome(i, -1, [True])
                        if i != 1 and j != n-1 and s[1] < r and s[1] < n-(j-i): 
                            max_radius = 2 * r
    return max_radius // 2 if max_radius > 0 else 0

