                    T[w][j] = (T[w][j] + dp[base[0][i]] * diff[base[1][j - i]]) % MOD
                    T[w][j] = (T[w][j] + dp[base[1][j - i]] * diff[base[0][i]]) % MOD
    return T[w][k] if T[w][k] * diff[w] < MOD else T[w][k] * diff[w] + MOD

