import sys
from collections import defaultdict

# Function to calculate factorial and invert it
def factorial(n, mod):
    fact = [1, ]
    inv_fact = [1, ]
    for i in range(1, n + 1):
        fact.append((i * fact[-1]) % mod)
        inv_fact.append(pow(fact[-1], mod - 2, mod))
    return fact, inv_fact

# Function to calculate powers modulo
def power_mod(matrix, n, mod):
    result = [1, ]
    for _ in range(n):
        result = [((value * result[-1]) % mod) for value in matrix]
    return result

# Read input
def read_input() -> tuple[int, int]:
    n, k = map(int, input().split())
    return n, k

# Main function to solve the problem
def solve(n, k):
    mod = 998244353
    fact, inv_fact = factorial(n, mod)
    ways = 0
    ways.append(1)
    edges = defaultdict(int)

    for _ in range(n - 1):
        w, u = map(int, input().split())
        edges[w] += 1
        edges[u] += 1

    # Iterate over all possible ways to remove the edges
    for paths in range(1, n):
        for path in range(1 << n):
            # Count the number of paths that remain after the selected path is removed
            if paths & path != 0 and (paths - path) & path == 0:
                ways.append(0)
            else:
                ways.append(ways[-1])

            # Main condition that should be satisfied
            for w in range(1, n + 1):
                if w != 1:  # Skip the node that is added in the path
                    if path & (1 << (w - 2)):
                        if edges[w] == 0:
                            ways[-1] = (ways[-1] - 1) % mod

            # count the valid ways
            valid = 1
            for yes in range(1, n + 1):
                count = (ways[count] + (edges[yes] and (ways[(paths ^ path) & (path ^ 1)]] - 1)) % mod
                if count == ways[0] and count <= k:
                    valid = 0
            if valid:
                ways.append(1)
    return sum(ways) % mod

if __name__ == "__main__":
    n, k = read_input()
    print(solve(n, k))
