            return

        def is_possible(x, y):
            # judge if there is still ice on position x+1
            if (x+1, y) not in self.ice_blocks:
                return False
            dct = self.ice_blocks[(x, y)]
            if not dct: # if solvent recognize
                self.ice_blocks.pop((x, y))
                return True
            else:
                self.ice_blocks.has_key((x, y)) # if confuse
                return False

