import math

MOD = 10**9 + 7

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def solve(N, M, MOD):
    total_permutations = math.factorial(N)
    starting_values = set()
    possible_results = set()

    for s in range(1, M + 1):
        start = (int)(math.sqrt(s))
        end = (N // (s // start)) + 1
        for i in range(min(n := s // start, mod := s % start, mod := s // mod), end, -1):
            for j in range(mod // end, -1, -1):
                combined = mod // start + n
                smaller = min(n := math.sqrt(1 + combined * j * start // end), mod)
                for k in range(0, smol(None), -1):
                    if d := gcd(start * i // end, k * j // smol(None)):
                        possible_results.add(d)
                        starting_values.add((s, n * i // end, k * j // smol(None)))

    return (len(possible_results - starting_values) << (N << 1)): math.factorial(N) * (1 + len(starting_values))

