from collections import defaultdict

def process_queries(n, queries, p, colors):
    parent = [-1] * (n + 1)
    parent[1] = 1
    stack = []
    stack.append(1) 
    color_stack = []
    for v in range(1, n + 1):
        if parent[v] == -1:
            stack.append(v)
            color_stack.append([(v,colors[v])])
        while len(stack) > 1:
            u = stack.pop()
            v = p[u]
            color_stack.sort(key=lambda x: x[1][1], reverse=True)
            for pair in reversed(color_stack):
                if v in pair[0]:
                    parent[v] = pair[1]
            stack.append(u)
            color_stack.append([(v,colors[v])])
    return parent

def query_color(n, queries, parent):
    result = []
    for i, v in queries:
        if i == 1:
            if v == 1 and parent[1] != -1:
                result.append("black")
            else:
                result.append("white")
        if i == 2:
            if v == 1:
                if len(parent[v]) > 0:
                    result.append("black")
                else:
                    result.extend(parent[v])
            else:
                result.append("white")
        if i == 3:
            if v == 1:
                result.append(parent[1])
            else:
                result.append(parent[v])
    return result

