from itertools import chain

def f_sol_naive_multiset(input_list: list, mod: int = 998244353) -> int:
    """
    Returns the number of different results the function f^k can take
    on an n-element array for k iterations.
    """
    one_input: set[int] = set()
    for ele in input_list:
        one_input.add(ele)

    input_set = set(map(tuple, one_input))
    memo = {}
    results = {tuple(map(tuple, input_set)): 1}
    mod_ = 998244353
    result = set()

    for step in range(k):
        repetitions = {}
        for group in input_set:
            representation = tuple(sorted(group))
            if representation not in repetitions:
                repetitions[representation] = 0
            for i in range(max(list(representation) + sorted([min(group), max(group)]))):
                rep = tuple(sorted([j - i for j in range(min(group) + i, max(group) + 1)]))
                if rep in repetitions:
                    repetitions[rep] += 1
                elif rep in results:
                    repetitions[rep] = results[rep] + 1
            for valor in results.values():
                if valor:
                    for i in range(0, max(group) - min(group) + 1):
                        new_representation = tuple(sorted([j - i for j in range(min(group) + i, max(group) + 1)]))
                        if new_representation not in repetitions:
                            repetitions[new_representation] = 0
                        repetitions[new_representation] += 1
                        if new_representation in memo:
                            memo[new_representation] += 1
                    for j in range(1, valor + 1):
                        new_representation = tuple(sorted([j * (j + i) for j in range(1, valor + 1)]))
                        if new_representation not in repetitions:
                            repetitions[new_representation] = 0
                        repetitions[new_representation] += 1
                        if new_representation in memo:
                            memo[new_representation] += 1
        for e in memo.values():
            result.add(tuple(sorted([e] * e)))
        input_set = set()
        for e in results:
            input_set.add(frozenset(list(e)))
        memo = results.copy()
        input_set = frozenset(chain.from_iterable(input_set))

    return len(result) % mod_


if __name__ == "__main__":
    n, k = map(int, input().strip().split())
    print(f_sol_naive_multiset(list(range(1, n + 1)), mod))
