from collections import defaultdict

def mark_vertex(graph, level):
    q = [(1, 0)]
    colors = defaultdict(set)
    colors[1].add(1)

    for v in level:
        while q:
            u, level_u = q.pop()
            if level_u > len(level) - v:
                return frozenset(colors[u])
            for to in graph[u]:
                if to not in colors[u]:
                    colors[u].add(to)
                    q.insert(0, (to, level_u + 1))

    return frozenset(colors[1])

