import math

def solve_fire_demon_attack(n, strengths):
    moves = []
    for index, strength in enumerate(strengths[1:], start=1):
        # If the current position has no fire demon
        if strength == 0:
            moves += moves[index+1:], 'L' * index, 'A' * (n-index)
