        # If the next position has a fire demon
        elif index == n and strengths[0] != 0:
            # Replace the first fire demon with an ice block and remove the rest
            new_strengths = [strengths[i+1] if i+1 < n else 0 for i in range(n)]
            return ''.join(moves[:-index+1] + ['AR'] + moves[index+1:])
