from bisect import bisect_right

def longest_increasing_subsequence(a, var):
    max_len = 0
    query = [-1] * len(a)
    for i in var:
        for j in range(len(a)):
            diff = abs(a[j] - i)
            idx = bisect_right(query, diff)
            if idx < len(query):
                max_len = max(max_len, idx + min(len(a) - 1, query[idx + 1]))
                query[idx + 1] = max(query[idx + 1], len(query) + (diff - query[idx]))
            else:
                query.append(min(len(a) - 1, diff - 1))
    return max_len

